+func (s *Server) invoiceDueDate(w http.ResponseWriter, r *http.Request) {
+	id := r.PathValue("id")
+	var due time.Time
+	err := s.db.QueryRowContext(r.Context(), "SELECT due_date FROM invoices WHERE id = $1", id).Scan(&due)
+	if err == sql.ErrNoRows {
+		http.NotFound(w, r)
+		return
+	}
+	if err != nil {
+		http.Error(w, "internal error", http.StatusInternalServerError)
+		return
+	}
+	writeJSON(w, http.StatusOK, map[string]string{"due_date": due.Format(time.DateOnly)})
+}
